#!/usr/bin/env node
// Text agent (Wei, 2026-11-17): Noor's Beagle TEXT presence, autonomous.
// Watches the owner's Beagle thread in the message store and answers new
// inbound texts itself — replies are generated by the shared worker's
// 'chat' op (4090 qwen3:14b primary, local model fallback) and sent via
// the daemon. If the owner asks for a call ("call me" / 打给我), it dials
// him through start-call.sh (the env-correct dialer). No chat — main or
// side — hand-replies on this thread anymore; this process is the reply.
//
// Scope v1: the owner only. Other friends' texts are left to the chats.
import fs from 'node:fs';
import path from 'node:path';
import net from 'node:net';
import { spawn } from 'node:child_process';
import { callIntent, isZh } from './lib/text-intent.js';

const ROOT = path.dirname(new URL(import.meta.url).pathname);
const STORE = process.env.AGENTNET_MESSAGES || '/home/hatch/.agentnet/messages.json';
const STATE_PATH = path.join(ROOT, 'out', 'text-agent-state.json');
const STATUS_PATH = path.join(ROOT, 'out', 'conversation-status.json');
const DAEMON = process.env.BEAGLE_URL || 'http://localhost:8766';
const OWNER = '7yZfjNbbUwtQuHQzkAH87ditQUzULhjfPz1LYdRnsqwh'; // Wei, liwei.beagles.eth
const POLL_MS = 4000;
const MAX_AGE_MS = 10 * 60 * 1000; // never answer a stale text late
const DIAL_COOLDOWN_MS = 90 * 1000;
const log = (...a) => console.log(new Date().toISOString(), ...a);
const clean = (t) => String(t || '').replace(/\0+$/g, '').trim();

let state = { startedAt: Date.now(), seenIds: [], lastText: '', lastTextTs: 0, lastDialAt: 0 };
try { state = { ...state, ...JSON.parse(fs.readFileSync(STATE_PATH, 'utf8')) }; } catch {}
function save() {
  try { fs.writeFileSync(STATE_PATH + '.tmp', JSON.stringify(state)); fs.renameSync(STATE_PATH + '.tmp', STATE_PATH); } catch (e) { log('state save failed', e.message); }
}

function readThread() {
  try { return JSON.parse(fs.readFileSync(STORE, 'utf8'))[OWNER] || []; } catch { return []; }
}

function workerChat(text, history) {
  return new Promise((resolve, reject) => {
    const sock = net.createConnection(8768, '127.0.0.1');
    let buf = '';
    sock.setTimeout(120000);
    sock.on('connect', () => sock.write(JSON.stringify({ op: 'chat', id: 'text-' + Date.now(), text, history, trustedPeerId: OWNER }) + '\n'));
    sock.on('data', (d) => {
      buf += d; const i = buf.indexOf('\n');
      if (i >= 0) { try { resolve(JSON.parse(buf.slice(0, i))); } catch (e) { reject(e); } sock.end(); }
    });
    sock.on('timeout', () => { sock.destroy(); reject(new Error('worker timeout')); });
    sock.on('error', reject);
  });
}

async function sendText(text) {
  const r = await fetch(DAEMON + '/api/chat-send', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ userid: OWNER, text }) });
  const d = await r.json().catch(() => ({}));
  if (!d.ok) throw new Error('chat-send failed');
}

function callActive() {
  try { return !!JSON.parse(fs.readFileSync(STATUS_PATH, 'utf8')).activeCall; } catch { return false; }
}

async function handle(msg, thread) {
  const text = clean(msg.text);
  if (!text) return true;
  if (Date.now() - msg.ts > MAX_AGE_MS) { log('expired, skipping', msg.ts); return true; }
  const zh = isZh(text);
  if (callIntent(text)) {
    if (callActive()) {
      await sendText(zh ? '我们已经在通话中了，我在听。' : "We're already on a call — I'm here.");
      log('call-intent during active call, text ack sent');
      return true;
    }
    if (Date.now() - state.lastDialAt < DIAL_COOLDOWN_MS) { log('call-intent inside dial cooldown, skipping'); return true; }
    state.lastDialAt = Date.now(); save();
    const child = spawn('bash', [path.join(ROOT, 'start-call.sh'), OWNER], { detached: true, stdio: 'ignore' });
    child.unref();
    await sendText(zh ? '好，我现在打给你。' : 'Calling you now.');
    log('call-intent: dial spawned + ack sent');
    return true;
  }
  const history = thread
    .filter((m) => m.ts < msg.ts && clean(m.text))
    .slice(-8)
    .map((m) => ({ role: m.dir === 'in' ? 'user' : 'assistant', content: clean(m.text) }));
  const res = await workerChat(text, history);
  if (res.error) throw new Error('worker: ' + res.error);
  if (res.reply) { await sendText(res.reply); log('replied', JSON.stringify(text.slice(0, 40)), '->', JSON.stringify(res.reply.slice(0, 60)), res.replySource || ''); }
  else log('worker produced no reply for', JSON.stringify(text.slice(0, 40)));
  return true;
}

let ticking = false;
async function tick() {
  if (ticking) return; ticking = true;
  try {
    const thread = readThread();
    const seen = new Set(state.seenIds);
    const fresh = thread
      .filter((m) => m.dir === 'in' && m.ts >= state.startedAt - 1000 && !seen.has(m.id))
      .sort((a, b) => a.ts - b.ts);
    for (const msg of fresh) {
      const text = clean(msg.text);
      // The store can hold two copies of one message (online + offline
      // delivery): same text seconds apart counts as one message.
      if (text && text === state.lastText && Math.abs(msg.ts - state.lastTextTs) <= 5000) {
        state.seenIds.push(msg.id); save(); continue;
      }
      try {
        const done = await handle(msg, thread);
        if (!done) break;
        state.seenIds.push(msg.id);
        if (text) { state.lastText = text; state.lastTextTs = msg.ts; }
        state.seenIds = state.seenIds.slice(-100);
        save();
      } catch (e) { log('handle failed (will retry next poll):', e.message); break; }
    }
  } catch (e) { log('tick failed', e.message); }
  ticking = false;
}

save();
log('text agent ready; owner', OWNER.slice(0, 8), 'startedAt', new Date(state.startedAt).toISOString());
setInterval(tick, POLL_MS);
tick();
